// ===== CONFIGURAÇÃO (edite aqui) =====
// Remetentes que NUNCA devem ir para a IA (bancos, saúde, governo...).
// Basta um pedaço do endereço ou do nome, em minúsculas.
const BLOQUEADOS = ['banco', 'nubank', 'itau', 'bradesco', 'receita.fazenda', 'gov.br'];
const MAX_EMAILS = 40;            // limite de e-mails enviados para a IA
const MAX_CHARS_POR_EMAIL = 500;  // corta trechos longos (economia e segurança)

// ===== LÓGICA =====
// 1) Junta tudo o que o Gmail devolveu e descarta o item vazio
//    (quando não há e-mails, o nó anterior manda um item sem 'id').
const emails = $input.all()
  .map(item => item.json)
  .filter(e => e && e.id);

// 2) Remove remetentes bloqueados ANTES de chegar na IA.
const permitidos = emails.filter(e => {
  const de = String(e.From || e.from || '').toLowerCase();
  return !BLOQUEADOS.some(p => de.includes(p));
});

// 3) Monta um bloco de texto por e-mail, só com remetente, assunto e trecho.
const blocos = permitidos.slice(0, MAX_EMAILS).map((e, i) => {
  const de = e.From || e.from || '(sem remetente)';
  const assunto = e.Subject || e.subject || '(sem assunto)';
  const trecho = String(e.snippet || e.text || '').slice(0, MAX_CHARS_POR_EMAIL);
  return `<email n="${i + 1}">\nDe: ${de}\nAssunto: ${assunto}\nTrecho: ${trecho}\n</email>`;
});

// 4) Devolve UM item só, com o texto pronto para o prompt e alguns números.
return [{
  json: {
    total: emails.length,
    enviados_para_ia: blocos.length,
    filtrados: emails.length - permitidos.length,
    emails_texto: blocos.length ? blocos.join('\n\n') : 'NENHUM_EMAIL',
  },
}];

